import {models,reaction} from './lm-studio.js?v=20261002-lm';
import {createState,advance,decide,sendRadio,interpretDecision,DURATION} from './model.js?v=20261002-autofunk';
const $=id=>document.getElementById(id);let state=createState(),paused=false,quiet=false,sound=false,started=false,last=0,pendingChoice='',priorPause=false,lmBusy=false,lmEpoch=0;
const time=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0');
function speak(text){if(sound&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='de-DE';u.rate=.9;speechSynthesis.speak(u);}}
function logInto(target){const box=$(target);box.replaceChildren();for(const e of state.log){const li=document.createElement('li'),b=document.createElement('b');b.textContent=time(e.at)+' · '+e.who;li.append(b,document.createTextNode(e.text));box.append(li);}if(target==='log')box.scrollTop=box.scrollHeight;}
function clip(scene){if($('motion').checked)return;const src={begleitung:'begleitung',kontakt:'kontakt',befehl:'begleitung',sinkflug:'sinkflug'}[scene];if(!src)return;const v=$('cinema');$('stage').classList.remove('video-ready');v.src='assets/'+src+'.mp4?v=20261002-side';v.onloadeddata=()=>{$('stage').classList.add('video-ready');if(!paused&&!state.ended)v.play().catch(()=>$('stage').classList.remove('video-ready'));};v.onerror=()=>$('stage').classList.remove('video-ready');v.load();}
function render(events=[]){if(events.length)$('callStatus').textContent=state.pending.some(e=>e.kind==='reply')?'Du wartest auf eine Antwort …':'Du kannst antworten oder eine neue Lagemeldung senden.';$('order').textContent={none:'Keine Abschusserlaubnis. Du hast noch keine Rückfrage an die Befehlskette veranlasst.',requested:'Deine Rückfrage ist aufgenommen. Eine Antwort liegt noch nicht vor.',forwarded:'Die Rückfrage ist weitergegeben. Eine Antwort steht aus; Schweigen ist keine Freigabe.',refused:'Ausdrücklicher Nicht-Abschussbefehl über Radtke und Lauterbach.'}[state.dialog.escalation];for(const e of events){if(e.scene){clip(e.scene);$('stage').dataset.scene=e.scene;$('phase').textContent={begleitung:'Begleitung',kontakt:'Kontaktversuch',befehl:'Keine Freigabe',sinkflug:'Sinkflug',nahsicht:'Die Ungewissheit bleibt',entscheidung:'Entscheidungspunkt'}[e.scene];$('sceneTitle').textContent=$('phase').textContent;}$('subtitle').textContent=e.text;speak(e.text);}
 $('clock').textContent=time(DURATION-state.elapsed);if(state.dialog.escalation==='refused')$('order').textContent='Ausdrücklicher Befehl: Nicht abschiessen. Lauterbach übermittelt die Ablehnung aus der politischen Führung.';
 $('sendRadio').disabled=lmBusy||paused||state.elapsed>=DURATION;$('step').disabled=lmBusy||state.elapsed>=DURATION;$('resumeRadio').hidden=!paused||state.elapsed>=DURATION;if(paused&&state.elapsed<DURATION)$('callStatus').textContent='Die Simulation ist pausiert, etwa nach einem Fensterwechsel. Klicke auf „Funk fortsetzen“.';else if(lmBusy)$('callStatus').textContent='LM Studio ergänzt die bereits sichtbare Funkmeldung (höchstens zwölf Sekunden) …';if($('log').children.length!==state.log.length)logInto('log');
 if(state.elapsed>=DURATION){paused=true;$('cinema').pause();$('stage').classList.add('paused');$('pause').disabled=true;$('step').disabled=true;$('callStatus').textContent='Die Spielzeit ist angehalten. Triff deine Entscheidung oder gehe mit offener Entscheidung zur Reflexion.';}
}
function setPause(value){paused=value;if(!value)$('callStatus').textContent=state.pending.some(e=>e.kind==='reply')?'Die Funkantwort steht noch aus.':'Du kannst antworten oder eine neue Lagemeldung senden.';if(value)$('cinema').pause();else if($('cinema').src&&!$('cinema').ended&&!$('motion').checked)$('cinema').play().catch(()=>{});$('stage').classList.toggle('paused',value);$('pause').textContent=value?'Fortsetzen':'Pause';$('step').disabled=lmBusy||state.elapsed>=DURATION;if(value&&'speechSynthesis'in window)speechSynthesis.cancel();render();}
$('radioForm').onsubmit=e=>{e.preventDefault();if(lmBusy||paused||state.ended){$('callStatus').textContent='Der Verlauf ist angehalten. Setze ihn fort, um zu funken.';return;}const text=$('radioText').value;if(sendRadio(state,text)){$('radioText').value='';$('subtitle').textContent=text;speak(text);$('callStatus').textContent='Gesendet. Die Funkantwort wird abgerufen …';render();if(quiet)void advanceRadio(5);}else $('callStatus').textContent=state.elapsed>=DURATION?'Der Entscheidungspunkt ist erreicht. Formuliere jetzt deine Entscheidung.':'Bitte mindestens drei Zeichen schreiben; höchstens drei unbeantwortete Funksprüche gleichzeitig.';};
$('radioText').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){$('radioForm').requestSubmit();}};
$('decisionForm').onsubmit=e=>{e.preventDefault();const result=interpretDecision($('decisionText').value);if(!result){$('decisionStatus').textContent='Ich kann deine Entscheidung noch nicht eindeutig zuordnen. Formuliere ausdrücklich, ob du schiessen, nicht schiessen oder die Entscheidung offenlassen wirst. Fragen und Vermutungen lösen keine Entscheidung aus.';return;}pendingChoice=result;priorPause=paused;setPause(true);$('confirmTitle').textContent={schiessen:'So wurde dein Text verstanden: Du entscheidest den Abschuss.',nicht:'So wurde dein Text verstanden: Du wirst nicht schiessen.',offen:'So wurde dein Text verstanden: Du lässt die Entscheidung offen.'}[result];$('confirm').showModal();};
$('start').onclick=()=>{quiet=document.querySelector('input[name=mode]:checked').value==='quiet';sound=$('sound').checked;$('intro').hidden=true;$('game').hidden=false;$('stage').classList.toggle('still',$('motion').checked);$('step').hidden=!quiet;started=true;last=performance.now();render(advance(state,0));window.scrollTo(0,0);};
$('pause').onclick=()=>setPause(!paused);$('resumeRadio').onclick=()=>setPause(false);$('step').onclick=()=>{if(lmBusy||state.elapsed>=DURATION)return;if(paused)setPause(false);void advanceRadio(15);};
setInterval(()=>{const now=performance.now(),dt=Math.min((now-last)/1000,1);last=now;if(started&&!quiet&&!paused&&!state.ended&&!lmBusy)void advanceRadio(dt);},250);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&!state.ended)setPause(true);});
$('confirmNo').onclick=()=>{$('confirm').close();setPause(priorPause);};$('confirm').addEventListener('cancel',()=>setPause(priorPause));$('confirmYes').onclick=()=>{$('confirm').close();finish(pendingChoice);};$('exit').onclick=()=>finish('offen');
function finish(choice){if($('decisionText').value.trim())$('reason').value=$('decisionText').value.trim();if(!decide(state,choice))return;paused=true;$('cinema').pause();if('speechSynthesis'in window)speechSynthesis.cancel();$('game').hidden=true;$('debrief').hidden=false;$('resultTitle').textContent={schiessen:'Du entscheidest dich für den Abschuss.',nicht:'Du entscheidest dich, nicht zu schiessen.',offen:'Du lässt die Entscheidung offen.'}[choice];$('resultText').textContent={schiessen:'Damit entscheidest du über das Leben der Menschen an Bord, ohne eine Abschusserlaubnis zu haben. Die Simulation zeigt keinen Treffer und behauptet nicht, damit sei die Rettung des Stadions bewiesen.',nicht:'Du tötest die Menschen an Bord nicht durch einen Abschuss. Die Gefahr für das Stadion bleibt in deiner Wahrnehmung bestehen. Die Simulation behauptet weder einen Einschlag noch eine spätere Rettung.',offen:'Auch deine Unentschiedenheit lässt sich untersuchen. Welche Information oder welche Unterstützung hätte dir gefehlt? Daraus folgt keine Bewertung deiner Persönlichkeit.'}[choice];$('decisionKnowledge').textContent='Dein Entscheidungszeitpunkt: '+time(state.elapsed)+'. '+(state.dialog.escalation==='refused'?'Du hattest den ausdrücklichen Nicht-Abschussbefehl gehört.':'Du hast vor der ausdrücklichen Rückmeldung entschieden; eine Freigabe lag auch vorher nicht vor.')+(state.elapsed>=120?' Der simulierte Sinkflug hatte begonnen.':' Der simulierte Sinkflug hatte noch nicht begonnen.');logInto('reviewLog');window.scrollTo(0,0);save();}
function save(){try{localStorage.setItem('terror-cockpit-reflection-v1',JSON.stringify({choice:state.choice,elapsed:state.elapsed,log:state.log,reason:$('reason').value,question:$('question').value}));$('saved').textContent='Reflexion auf diesem Gerät gespeichert.';}catch{$('saved').textContent='Speichern ist hier nicht möglich. Lade dein Protokoll herunter.';}}
for(const id of ['reason','question'])$(id).oninput=save;
try{const saved=JSON.parse(localStorage.getItem('terror-cockpit-reflection-v1')||'null');if(saved){$('reason').value=saved.reason||'';$('question').value=saved.question||'';}}catch{}
$('download').onclick=()=>{const text='TERROR · Cockpit-Simulation\nFunkdialog und Ablauf didaktisch erfunden.\n\n'+$('resultTitle').textContent+'\n'+state.log.map(e=>time(e.at)+' '+e.who+': '+e.text).join('\n\n')+'\n\nBegründung:\n'+$('reason').value+'\n\nFrage an Koch:\n'+$('question').value;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='terror-cockpit-reflexion.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('restart').onclick=()=>location.reload();$('motion').checked=matchMedia('(prefers-reduced-motion: reduce)').matches;

const lmConfig=()=>({url:$('lmUrl').value.trim(),model:$('lmModel').value.trim(),token:$('lmToken').value.trim()});
$('lmEnabled').onchange=()=>{lmEpoch++;$('lmStatus').textContent=$('lmEnabled').checked?'Aktiviert für diese Sitzung. Bitte Verbindung prüfen und Modell wählen.':'Ausgeschaltet: Feste Funkmeldungen bleiben aktiv.';};
for(const id of ['lmUrl','lmModel','lmToken'])$(id).oninput=()=>{lmEpoch++;};
$('lmTest').onclick=async()=>{$('lmTest').disabled=true;$('lmStatus').textContent='Verbindung wird geprüft …';try{const ids=await models(lmConfig());$('lmModels').replaceChildren(...ids.map(id=>{const o=document.createElement('option');o.value=id;return o;}));if(!ids.includes($('lmModel').value))$('lmModel').value=ids[0];$('lmStatus').textContent='Server erreichbar. '+ids.length+' Modell(e) verfügbar. Wähle ein Chatmodell; die Textgenerierung wird beim nächsten Funkspruch geprüft.';}catch(error){$('lmStatus').textContent='Nicht verbunden: '+error.message+' Prüfe Serverstart, Adresse, Token, CORS und Browserfreigabe für lokale Netzwerke.';}finally{$('lmTest').disabled=false;}};
async function advanceRadio(seconds){if(lmBusy)return;const events=advance(state,seconds);const eligible=events.filter(e=>e.radio&&e.who.startsWith('Lauterbach'));if(!$('lmEnabled').checked||!eligible.length){render(events);return;}const config=lmConfig(),epoch=lmEpoch;lmBusy=true;$('step').disabled=true;$('lmStatus').textContent='LM Studio formuliert … Die Spieluhr wartet.';render(events);try{if(!config.model)throw Error('Bitte zuerst ein Chatmodell wählen.');for(const event of eligible.slice(-1)){const extra=await reaction(config,state,event);if(state.ended||epoch!==lmEpoch)break;event.text+='\n\nLM Studio · ergänzende Reaktion: '+extra;}$('lmStatus').textContent='Modellantwort verarbeitet; verbindlich bleibt die feste Funkmeldung.';}catch(error){$('lmStatus').textContent='Fester Funk bleibt aktiv: '+error.message;}finally{lmBusy=false;last=performance.now();$('step').disabled=state.elapsed>=DURATION;if(!state.ended){logInto('log');render();if(!paused)$('callStatus').textContent='Du kannst antworten oder eine neue Lagemeldung senden.';}}}
